'use strict';

/**
* Generates random 32-bit integers for seed generation.
*
* This module generates random 32-bit unsigned integer seed values
* using Math.random(). These are used to seed the Xorshift128+ PRNG
* when no explicit seed is provided.
*
* Two 32-bit values are combined to create a 64-bit seed:
* seed = (high << 32) | low
*
* This provides better entropy than using a single 32-bit value.
*/

// MODULES //

var randu = require( '@stdlib/random/base/randu' );
var floor = require( '@stdlib/math/base/special/floor' );
var BigInt = require( '@stdlib/bigint/ctor' );

/**
* Generates a random 32-bit unsigned integer.
*
* @private
* @returns {bigint} random 32-bit value as BigInt
*
* @example
* var seed = randi32();
* // throws <bigint>
*/
function randi32() {
	var seed;
	var high;
	var low;

	// Generate two 32-bit values and combine them into a 64-bit value
	high = floor( randu() * 0x100000000 );
	low = floor( randu() * 0x100000000 );
	seed = (BigInt( high ) << BigInt(32)) | BigInt( low );

	// Ensure non-zero seed
	if ( seed === BigInt(0) ) {
		seed = BigInt(1);
	}

	return seed;
}


// EXPORTS //

module.exports = randi32;
